 export function createGitOps(cwd: string): GitOps {
@@ -131,6 +139,50 @@ export function createGitOps(cwd: string): GitOps {
         return undefined; // no commits yet
       }
     },
+
+    async push(branch) {
+      try {
+        // Explicit refspec, no --force, no upstream tracking games: the only
+        // branch this run may ever touch is its own.
+        await git(cwd, ["push", "origin", `${branch}:${branch}`]);
+        return { ok: true };
+      } catch (error) {
+        const err = error as { stderr?: string; message?: string };
+        return { ok: false, error: (err.stderr || err.message || "").trim() };
+      }
+    },
+
+    async diffstatAgainst(base) {
+      try {
+        // Three dots: what the branch added, not what `base` moved on to.
+        const { stdout } = await git(cwd, ["diff", "--stat", `${base}...HEAD`]);
+        return stdout;
+      } catch {
+        return "";
+      }
+    },
+
+    async subjectsSince(base) {
+      try {
+        const { stdout } = await git(cwd, [
+          "log",
+          "--format=%H%x00%s",
+          `${base}..HEAD`,
+        ]);
+        const out: Record<string, string> = {};
+        for (const line of stdout.split("\n")) {
+          const [hash, subject] = line.split("\0");
+          if (hash && subject) out[hash] = subject;
+        }
+        return out;
+      } catch {
+        return {};
+      }
+    },
+
+    async addWorktree(dir, branch) {
+      await git(cwd, ["worktree", "add", "-b", branch, dir]);
+    },
   };
 }

diff --git a/apps/core/src/autonomous/night-ops.test.ts b/apps/core/src/autonomous/night-ops.test.ts
new file mode 100644
index 00000000..cf6088cd
--- /dev/null
+++ b/apps/core/src/autonomous/night-ops.test.ts
@@ -0,0 +1,203 @@
+// =============================================================================
+// Reading a night afterwards — crashed-run detection, listing, regeneration.
+// Spec: docs/specs/2026-09-28-overnight-runs.md §4.11, §5.4
+// =============================================================================
+
+import test from "node:test";
+import assert from "node:assert/strict";
+import * as fs from "fs";
+import * as os from "os";
+import * as path from "path";
+import {
+  buildReport,
+  findNightRun,
+  listNightRuns,
+  pidAlive,
+  reconcileCrashed,
+  requestStop,
+  statusLine,
+} from "./night-ops.js";
+import { appendDecision, appendIteration, reportPathFor } from "./night-store.js";
+import { readManifest, writeManifest } from "./run-store.js";
+import { DEFAULT_RUN_LIMITS, EMPTY_USAGE, type RunManifest } from "./types.js";
+
+function withRunsHome<T>(fn: () => T): T {
+  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "night-ops-"));
+  const previous = process.env.FREECODE_RUNS_HOME;
+  process.env.FREECODE_RUNS_HOME = dir;
+  try {
+    return fn();
+  } finally {
+    if (previous === undefined) delete process.env.FREECODE_RUNS_HOME;
+    else process.env.FREECODE_RUNS_HOME = previous;
+    fs.rmSync(dir, { recursive: true, force: true });
+  }
+}
+
+function manifest(over: Partial<RunManifest> = {}): RunManifest {
+  return {
+    runId: "run-1",
+    status: "running",
+    createdAt: 1_000,
+    startedAt: 1_000,
+    projectPath: "/repo",
+    provider: "anthropic",
+    model: "claude-opus-5",
+    limits: DEFAULT_RUN_LIMITS,
+    usage: EMPTY_USAGE,
+    turns: 0,
+    verifyCommand: "",
+    taskCardCount: 0,
+    night: {
+      objective: "make it faster",
+      branch: "night/make-it-faster",
+      iterations: 3,
+      commits: ["aaa111"],
+      waitedMs: 0,
+      fallbackIterations: [],
+    },
+    ...over,
+  };
+}
+
+test("a live pid is alive; a freed one is not", () => {
+  assert.equal(pidAlive(process.pid), true);
+  assert.equal(pidAlive(undefined), false);
+  // 2^22 is above Linux's default pid_max, so nothing can hold it.
+  assert.equal(pidAlive(4_194_304), false);
+});
+
+test("a run whose process is gone is recorded as crashed, not left running", () => {
+  withRunsHome(() => {
+    // The whole point of §5.4: a terminal closed at 3am leaves a manifest that
+    // claims the run is still going, forever.
+    writeManifest(manifest({ pid: 4_194_304 }));
+    const reconciled = reconcileCrashed(readManifest("run-1")!);
+    assert.equal(reconciled.status, "crashed");
+    assert.ok(reconciled.endedAt, "a crashed run still gets an end time");
+    // Persisted, so `status` and `list` agree and a resume knows what it found.
+    assert.equal(readManifest("run-1")!.status, "crashed");
+  });
+});
+
+test("a run whose process is alive is left alone", () => {
+  withRunsHome(() => {
+    writeManifest(manifest({ pid: process.pid }));
+    assert.equal(reconcileCrashed(readManifest("run-1")!).status, "running");
+  });
+});
+
+test("a finished run is never re-judged by its pid", () => {
+  withRunsHome(() => {
+    // Its pid is long gone by definition; that is not a crash.
+    writeManifest(manifest({ status: "completed", pid: 4_194_304 }));
+    assert.equal(reconcileCrashed(readManifest("run-1")!).status, "completed");
+  });
+});
+
+test("listing shows night runs only, newest first", () => {
+  withRunsHome(() => {
+    writeManifest(manifest({ runId: "old", createdAt: 1, status: "completed" }));
+    writeManifest(manifest({ runId: "new", createdAt: 999, status: "completed" }));
+    // An old autonomous-spec run has no `night` block and is not one of these.
+    writeManifest({ ...manifest({ runId: "other" }), night: undefined });
+    assert.deepEqual(
+      listNightRuns().map((m) => m.runId),
+      ["new", "old"],
+    );
+  });
+});
+
+test("a run is found by id or by branch — the branch is what survives the night", () => {
+  withRunsHome(() => {
+    writeManifest(manifest({ runId: "abc", status: "completed" }));
+    assert.equal(findNightRun("abc")?.runId, "abc");
+    assert.equal(findNightRun("night/make-it-faster")?.runId, "abc");
+    assert.equal(findNightRun("nope"), undefined);
+    assert.equal(findNightRun()?.runId, "abc", "no argument means the newest");
+  });
+});
+
+test("the status line carries the numbers without the report", () => {
+  const line = statusLine(manifest({ status: "completed" }));
+  assert.match(line, /run-1/);
+  assert.match(line, /3 it/);
+  assert.match(line, /1 commit/);
+  assert.match(line, /night\/make-it-faster/);
+});
+
+test("stop is only for a running run, and is recorded rather than signalled", () => {
+  withRunsHome(() => {
+    writeManifest(manifest({ pid: process.pid }));
+    assert.equal(requestStop(readManifest("run-1")!), true);
+    assert.equal(readManifest("run-1")!.cancelRequested, true);
+
+    writeManifest(manifest({ runId: "done", status: "completed" }));
+    assert.equal(requestStop(readManifest("done")!), false);
+  });
+});
+
+test("a crashed run still gets a report, regenerated from its logs", () => {
+  withRunsHome(() => {
+    // The reason report.ts is pure: this run never reached its own exit path.
+    writeManifest(manifest({ status: "crashed", endedAt: 5_000 }));
+    appendIteration("run-1", {
+      kind: "iteration",
+      n: 1,
+      sessionId: "s1",
+      startedAt: 1_000,
+      endedAt: 2_000,
+      turns: 3,
+      commit: "aaa111",
+      summary: "cached the tree",
+    });
+    appendDecision("run-1", {
+      kind: "needs_human",
+      iteration: 1,
+      at: 1,
+      item: "needs a CI token",
+    });
+
+    const markdown = buildReport(readManifest("run-1")!);
+    assert.match(markdown, /# Night run run-1 — make it faster/);
+    assert.match(markdown, /## Needs you \(1\)/);
+    assert.match(markdown, /needs a CI token/);
+    assert.match(markdown, /cached the tree/);
+    // Written where `freecode night report` will find it.
+    assert.equal(fs.readFileSync(reportPathFor("run-1"), "utf-8"), markdown);
+  });
+});
+
+test("regenerating twice produces the same report", () => {
+  withRunsHome(() => {
+    writeManifest(manifest({ status: "completed", endedAt: 5_000 }));
+    appendIteration("run-1", {
+      kind: "iteration",
+      n: 1,
+      sessionId: "s1",
+      startedAt: 1_000,
+      endedAt: 2_000,
+      turns: 3,
+      commit: "aaa111",
+    });
+    assert.equal(
+      buildReport(readManifest("run-1")!),
+      buildReport(readManifest("run-1")!),
+    );
+  });
+});
+
+test("a secret in a decision never reaches the report", () => {
+  withRunsHome(() => {
+    writeManifest(manifest({ status: "completed", endedAt: 5_000 }));
+    appendDecision("run-1", {
+      kind: "needs_human",
+      iteration: 1,
+      at: 1,
+      item: "set ANTHROPIC_API_KEY=sk-ant-abcdefghijklmnopqrstuv on the runner",
+    });
+    const markdown = buildReport(readManifest("run-1")!);
+    assert.doesNotMatch(markdown, /sk-ant-abcdefghijklmnopqrstuv/);
+    assert.match(markdown, /redacted/);
+  });
+});

diff --git a/apps/core/src/autonomous/night-ops.ts b/apps/core/src/autonomous/night-ops.ts
new file mode 100644
index 00000000..b1f8f1ad
--- /dev/null
+++ b/apps/core/src/autonomous/night-ops.ts
@@ -0,0 +1,126 @@
+// =============================================================================
+// Reading a night afterwards: status, report, list.
+//
+// All of it folds the run directory — manifest + the two jsonl logs — so it
+// works on a run this process never started, and on one that died mid-iteration.
+// Spec: docs/specs/2026-09-28-overnight-runs.md §4.11, §5.4
+// =============================================================================
+
+import * as fs from "fs";
+import { readDecisions, readIterations, reportPathFor } from "./night-store.js";
+import { renderReport, duration } from "./report.js";
+import { listRuns, readManifest, updateManifest } from "./run-store.js";
+import type { RunManifest } from "./types.js";
+
+/**
+ * Whether the process that owns a run is still alive.
+ *
+ * `kill(pid, 0)` tests existence without signalling. The pid could have been
+ * recycled onto an unrelated process, which would read as "still running" —
+ * accepted: the alternative is a liveness handshake for a foreground command
+ * whose terminal the user can simply look at.
+ */
+export function pidAlive(pid: number | undefined): boolean {
+  if (pid === undefined) return false;
+  try {
+    process.kill(pid, 0);
+    return true;
+  } catch (error) {
+    // EPERM means it exists and belongs to someone else — still alive.
+    return (error as NodeJS.ErrnoException).code === "EPERM";
+  }
+}
+
+/**
+ * A run whose manifest says `running` but whose pid is gone did not stop, it
+ * DIED — terminal closed, OOM, crash. Recorded on read so `status` and `list`
+ * agree, and so a later resume knows what it is resuming.
+ */
+export function reconcileCrashed(manifest: RunManifest): RunManifest {
+  if (manifest.status !== "running" || pidAlive(manifest.pid)) return manifest;
+  const crashed: RunManifest = {
+    ...manifest,
+    status: "crashed",
+    endedAt: manifest.endedAt ?? Date.now(),
+  };
+  updateManifest(manifest.runId, () => crashed);
+  return crashed;
+}
+
+/** Night runs only, newest first, with dead ones marked crashed. */
+export function listNightRuns(): RunManifest[] {
+  return listRuns()
+    .filter((m) => m.night !== undefined)
+    .map(reconcileCrashed);
+}
+
+/** The newest night run, or the one whose branch matches. */
+export function findNightRun(idOrBranch?: string): RunManifest | undefined {
+  const runs = listNightRuns();
+  if (!idOrBranch) return runs[0];
+  return (
+    runs.find((m) => m.runId === idOrBranch) ??
+    runs.find((m) => m.night?.branch === idOrBranch)
+  );
+}
+
+export function statusLine(manifest: RunManifest): string {
+  const night = manifest.night;
+  if (!night) return `${manifest.runId}  (not a night run)`;
+  const elapsed =
+    manifest.startedAt !== undefined
+      ? duration((manifest.endedAt ?? Date.now()) - manifest.startedAt)
+      : "—";
+  const parts = [
+    manifest.runId.padEnd(10),
+    manifest.status.padEnd(9),
+    `${night.iterations} it`.padEnd(6),
+    `${night.commits.length} commit${night.commits.length === 1 ? "" : "s"}`.padEnd(10),
+    elapsed.padEnd(7),
+    night.waitedMs > 0 ? `waited ${duration(night.waitedMs)}` : "",
+  ];
+  return `${parts.join(" ")}  ${night.branch}`;
+}
+
+/**
+ * Regenerate the report from the logs and write it.
+ *
+ * The run writes one at exit; this is how a CRASHED run still gets one, and
+ * why nothing in `report.ts` reads anything but its input.
+ */
+export function buildReport(
+  manifest: RunManifest,
+  extras: { diffstat?: string; subjects?: Record<string, string> } = {},
+): string {
+  const night = manifest.night;
+  if (!night) throw new Error(`run ${manifest.runId} is not a night run`);
+  const markdown = renderReport({
+    runId: manifest.runId,
+    night,
+    status: manifest.status,
+    startedAt: manifest.startedAt,
+    endedAt: manifest.endedAt,
+    provider: manifest.provider,
+    model: manifest.model,
+    usd: manifest.usage.usd,
+    records: readIterations(manifest.runId),
+    decisions: readDecisions(manifest.runId),
+    ...extras,
+  });
+  fs.writeFileSync(reportPathFor(manifest.runId), markdown, "utf-8");
+  return markdown;
+}
+
+/** Ask a running night to stop at the next iteration boundary. */
+export function requestStop(manifest: RunManifest): boolean {
+  if (manifest.status !== "running") return false;
+  return (
+    updateManifest(manifest.runId, (m) => ({ ...m, cancelRequested: true })) !==
+    null
+  );
+}
+
+export function readNightManifest(runId: string): RunManifest | undefined {
+  const m = readManifest(runId);
+  return m ? reconcileCrashed(m) : undefined;
+}

