@@ -62,7 +89,7 @@ export function appendIteration(
   runId: string,
   record: IterationRecord | WaitRecord,
 ): void {
-  append(iterationsPath(runId), `${scrub(JSON.stringify(record))}\n`);
+  append(iterationsPath(runId), `${JSON.stringify(scrubFields(record))}\n`);
